INSERT INTO `recipes` VALUES (1,1,'Idli','idli','Soft, fluffy and delicious South Indian steamed rice cakes, perfect with sambar and chutney.',15,15,4,'idly.jpg','https://www.youtube.com/embed/Ayo80PIb-Qg','Soak the rice and urad dal separately. Grind them into a smooth batter, mix them together and allow the batter to ferment before steaming.','[{\"title\": \"Soak\", \"description\": \"Wash and soak the rice and urad dal separately for several hours.\", \"step_number\": 1}, {\"title\": \"Grind\", \"description\": \"Grind the soaked rice and urad dal into a smooth batter.\", \"step_number\": 2}, {\"title\": \"Ferment\", \"description\": \"Mix the batter well and allow it to ferment until it becomes light and fluffy.\", \"step_number\": 3}, {\"title\": \"Steam\", \"description\": \"Pour the batter into idli moulds and steam until the idlis are cooked.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Remove the idlis carefully and serve hot with chutney and sambar.\", \"step_number\": 5}]'),(2,1,'Masala Dosa','masala-dosa','Crispy golden dosa filled with a delicious spiced potato filling.',20,20,4,'dosa.jpg','https://www.youtube.com/embed/J75VQSxOtdo','Prepare the potato filling and spread dosa batter thinly on a hot pan. Add the filling and fold the dosa.','[{\"title\": \"Prepare Batter\", \"description\": \"Keep the dosa batter ready.\", \"step_number\": 1}, {\"title\": \"Prepare Filling\", \"description\": \"Boil and mash the potatoes and prepare the filling.\", \"step_number\": 2}, {\"title\": \"Make Dosa\", \"description\": \"Spread the batter thinly on a hot pan.\", \"step_number\": 3}, {\"title\": \"Add Filling\", \"description\": \"Place the potato filling in the centre.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Fold the dosa and serve hot.\", \"step_number\": 5}]'),(3,1,'Ven Pongal','ven-pongal','A comforting South Indian dish made with rice and moong dal.',10,25,4,'pongal.jpg','https://www.youtube.com/embed/rjdpb2UsFJM','Cook rice and moong dal together until soft. Add the prepared ingredients and mix well.','[{\"title\": \"Wash\", \"description\": \"Wash the rice and moong dal thoroughly.\", \"step_number\": 1}, {\"title\": \"Cook\", \"description\": \"Cook them together until soft.\", \"step_number\": 2}, {\"title\": \"Prepare\", \"description\": \"Prepare the ginger and cashews.\", \"step_number\": 3}, {\"title\": \"Mix\", \"description\": \"Add ghee and the prepared ingredients.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Mix well and serve hot.\", \"step_number\": 5}]'),(4,1,'Poori Masala','poori-masala','Soft and fluffy pooris served with a flavorful potato masala.',20,20,4,'poori.jpg','https://www.youtube.com/embed/Aokks98tw_I','Prepare a soft dough, roll small portions and cook the pooris. Prepare the potato masala separately.','[{\"title\": \"Prepare Dough\", \"description\": \"Prepare a soft dough using wheat flour and water.\", \"step_number\": 1}, {\"title\": \"Prepare Masala\", \"description\": \"Boil potatoes and prepare the potato masala.\", \"step_number\": 2}, {\"title\": \"Roll\", \"description\": \"Roll small portions of dough into round pooris.\", \"step_number\": 3}, {\"title\": \"Cook\", \"description\": \"Cook the pooris until they puff up.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Serve hot with potato masala.\", \"step_number\": 5}]'),(5,1,'Upma','upma','A simple and delicious South Indian breakfast made with roasted semolina.',10,20,4,'upma.jpg','https://www.youtube.com/embed/cAoYsLXUKGI','Roast the rava, cook the vegetables, add water and slowly mix in the roasted rava until soft and fluffy.','[{\"title\": \"Roast Rava\", \"description\": \"Dry roast the rava until lightly golden.\", \"step_number\": 1}, {\"title\": \"Cook Vegetables\", \"description\": \"Cook the onion, carrot, green chilli and ginger.\", \"step_number\": 2}, {\"title\": \"Add Water\", \"description\": \"Add water and bring it to a boil.\", \"step_number\": 3}, {\"title\": \"Add Rava\", \"description\": \"Slowly add rava while continuously stirring.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Cook until soft and serve hot.\", \"step_number\": 5}]'),(6,1,'Aloo Paratha','aloo-paratha','Soft and flavorful Indian flatbread stuffed with a delicious spiced potato filling.',20,25,4,'aloo.jpg','https://www.youtube.com/embed/jLmYDZ2zjSg','Prepare a soft wheat dough and make a spiced potato filling. Stuff the filling inside the dough, roll it gently and cook the parathas on a hot pan.','[{\"title\": \"Prepare Dough\", \"description\": \"Mix wheat flour with water and prepare a soft dough.\", \"step_number\": 1}, {\"title\": \"Prepare Filling\", \"description\": \"Boil and mash the potatoes. Mix them with onion, green chilli, coriander and spices.\", \"step_number\": 2}, {\"title\": \"Stuff\", \"description\": \"Take a portion of dough, add the potato filling and seal it properly.\", \"step_number\": 3}, {\"title\": \"Roll\", \"description\": \"Gently roll the stuffed dough into a round paratha.\", \"step_number\": 4}, {\"title\": \"Cook\", \"description\": \"Cook the paratha on a hot pan until both sides are golden and serve hot.\", \"step_number\": 5}]'),(7,1,'Chole Bhature','chole-bhature','A popular North Indian breakfast consisting of spicy chickpea curry served with fluffy bhature.',20,30,4,'bhature.webp','https://www.youtube.com/embed/80FZbnl40q4','Cook the chickpeas with spices to prepare chole and make a soft dough for bhature. Roll and fry the bhature until they puff up.','[{\"title\": \"Soak Chickpeas\", \"description\": \"Soak chickpeas in water for several hours or overnight.\", \"step_number\": 1}, {\"title\": \"Cook Chole\", \"description\": \"Cook the chickpeas and prepare a flavorful curry using onion, tomato and spices.\", \"step_number\": 2}, {\"title\": \"Prepare Dough\", \"description\": \"Prepare a soft dough using wheat flour and water.\", \"step_number\": 3}, {\"title\": \"Make Bhature\", \"description\": \"Roll small portions of dough and cook them until they puff up.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Serve hot bhature with spicy chole.\", \"step_number\": 5}]'),(8,1,'Poha','poha','A light and tasty breakfast made with flattened rice, vegetables and mild spices.',10,15,4,'poha.jpg','https://www.youtube.com/embed/X35gOeA8l_4','Wash the poha gently and cook it with sautéed vegetables, peanuts and spices until soft and flavorful.','[{\"title\": \"Wash Poha\", \"description\": \"Wash the poha gently with water and drain it.\", \"step_number\": 1}, {\"title\": \"Prepare Vegetables\", \"description\": \"Cook onion, potato and green chilli until soft.\", \"step_number\": 2}, {\"title\": \"Add Peanuts\", \"description\": \"Add peanuts and lightly roast them with the vegetables.\", \"step_number\": 3}, {\"title\": \"Add Poha\", \"description\": \"Add the washed poha and mix everything gently.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Cook for a few minutes and garnish with coriander leaves.\", \"step_number\": 5}]'),(9,1,'Bread Omelette','bread-omelette','A quick and delicious breakfast made with fluffy egg omelette served with toasted bread.',5,10,2,'omblete.jpg','https://www.youtube.com/embed/QzuXzLtYUpE','Beat the eggs with vegetables and spices, cook the omelette on a pan and serve it with toasted bread.','[{\"title\": \"Beat Eggs\", \"description\": \"Break the eggs into a bowl and beat them well.\", \"step_number\": 1}, {\"title\": \"Add Ingredients\", \"description\": \"Add chopped onion, green chilli, coriander and pepper.\", \"step_number\": 2}, {\"title\": \"Cook Omelette\", \"description\": \"Pour the egg mixture onto a hot pan and cook both sides.\", \"step_number\": 3}, {\"title\": \"Toast Bread\", \"description\": \"Toast the bread slices until lightly crisp.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Place the omelette with toasted bread and serve hot.\", \"step_number\": 5}]'),(10,1,'French Toast','french-toast','Golden and delicious bread slices dipped in a sweet egg mixture and cooked until lightly crisp.',5,10,2,'toast.jpg','https://www.youtube.com/embed/qrWIlXUHvuE','Prepare a sweet egg and milk mixture, dip the bread slices in it and cook them on a pan until golden.','[{\"title\": \"Prepare Mixture\", \"description\": \"Beat eggs with milk, sugar and vanilla essence.\", \"step_number\": 1}, {\"title\": \"Dip Bread\", \"description\": \"Dip each bread slice into the mixture evenly.\", \"step_number\": 2}, {\"title\": \"Heat Pan\", \"description\": \"Heat a pan and add a little butter.\", \"step_number\": 3}, {\"title\": \"Cook\", \"description\": \"Cook the soaked bread slices on both sides until golden.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Serve warm with fruits or your preferred topping.\", \"step_number\": 5}]'),(11,1,'Pancakes','pancakes','Soft and fluffy pancakes that make a simple and delicious breakfast.',10,15,4,'pancake.jpg','https://www.youtube.com/embed/mWHYhtprT5M','Mix the ingredients into a smooth batter and cook small portions on a hot pan until golden on both sides.','[{\"title\": \"Prepare Batter\", \"description\": \"Mix flour, sugar and baking powder in a bowl.\", \"step_number\": 1}, {\"title\": \"Add Wet Ingredients\", \"description\": \"Add milk and egg and mix until a smooth batter forms.\", \"step_number\": 2}, {\"title\": \"Heat Pan\", \"description\": \"Heat a pan and lightly grease it with butter.\", \"step_number\": 3}, {\"title\": \"Cook Pancakes\", \"description\": \"Pour a small amount of batter and cook both sides until golden.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Stack the pancakes and serve warm with your preferred topping.\", \"step_number\": 5}]'),(12,1,'Vegetable Sandwich','vegetable-sandwich','A fresh and tasty sandwich filled with colorful vegetables and a flavorful spread.',10,10,2,'sandwich.jpg','https://www.youtube.com/embed/DoeenfPeZdc','Spread butter on bread slices, arrange fresh vegetables between the slices and toast the sandwich until lightly crisp.','[{\"title\": \"Prepare Vegetables\", \"description\": \"Wash and slice the carrot, cucumber, tomato and capsicum.\", \"step_number\": 1}, {\"title\": \"Prepare Bread\", \"description\": \"Spread butter evenly on the bread slices.\", \"step_number\": 2}, {\"title\": \"Add Vegetables\", \"description\": \"Arrange the sliced vegetables on the bread.\", \"step_number\": 3}, {\"title\": \"Make Sandwich\", \"description\": \"Place another bread slice on top and gently press it.\", \"step_number\": 4}, {\"title\": \"Toast\", \"description\": \"Toast the sandwich on a pan until lightly golden and serve.\", \"step_number\": 5}]'),(13,1,'Cornflakes with Milk','cornflakes','A quick and easy breakfast made with crunchy cornflakes and fresh milk.',5,0,2,'corn.jpg','https://www.youtube.com/embed/zxtdjfGVqIg','Add cornflakes to a bowl, pour fresh milk over them and add fruits, nuts and honey.','[{\"title\": \"Add Cornflakes\", \"description\": \"Place cornflakes in a serving bowl.\", \"step_number\": 1}, {\"title\": \"Add Milk\", \"description\": \"Pour fresh milk over the cornflakes.\", \"step_number\": 2}, {\"title\": \"Add Fruits\", \"description\": \"Add sliced banana or other fruits.\", \"step_number\": 3}, {\"title\": \"Add Nuts\", \"description\": \"Add your preferred nuts.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Add honey and serve immediately.\", \"step_number\": 5}]'),(14,1,'Oatmeal','oatmeal','A warm and comforting breakfast made with oats, milk and fresh fruits.',5,10,2,'oat.jpg','https://www.youtube.com/embed/7QrA96GEvTM','Cook oats with milk until soft and creamy. Add fresh fruits, nuts and honey before serving.','[{\"title\": \"Heat Milk\", \"description\": \"Pour milk into a pan and heat it gently.\", \"step_number\": 1}, {\"title\": \"Add Oats\", \"description\": \"Add oats to the warm milk and stir well.\", \"step_number\": 2}, {\"title\": \"Cook\", \"description\": \"Cook until the oats become soft and creamy.\", \"step_number\": 3}, {\"title\": \"Add Toppings\", \"description\": \"Add sliced fruits and nuts.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Add a little honey and serve warm.\", \"step_number\": 5}]'),(15,1,'Fruit Salad','fruit-salad','A colorful and refreshing breakfast made with a variety of fresh fruits.',10,0,4,'salad.jpg','https://www.youtube.com/embed/nTm-_KujooY','Wash and cut the fruits into small pieces, combine them in a bowl and add a little honey before serving.','[{\"title\": \"Wash Fruits\", \"description\": \"Wash all the fruits thoroughly with clean water.\", \"step_number\": 1}, {\"title\": \"Cut Fruits\", \"description\": \"Peel and cut the fruits into small pieces.\", \"step_number\": 2}, {\"title\": \"Combine\", \"description\": \"Add all the cut fruits to a large bowl.\", \"step_number\": 3}, {\"title\": \"Add Honey\", \"description\": \"Drizzle a little honey over the fruits.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Mix gently and serve the fresh fruit salad.\", \"step_number\": 5}]'),(16,2,'Vegetable Biryani','vegetable-biryani','A flavorful and aromatic rice dish cooked with fresh vegetables and fragrant spices.',20,30,4,'bri.jpg','https://www.youtube.com/embed/X4f6bv-Modg','Wash and soak the rice. Cook the vegetables with onion and tomato, add the spices and combine with partially cooked rice. Cook together until the rice is fully done.','[{\"title\": \"Prepare Rice\", \"description\": \"Wash and soak the basmati rice before cooking.\", \"step_number\": 1}, {\"title\": \"Cook Vegetables\", \"description\": \"Cook the chopped vegetables with onion and tomato.\", \"step_number\": 2}, {\"title\": \"Add Rice\", \"description\": \"Add the partially cooked rice to the vegetable mixture.\", \"step_number\": 3}, {\"title\": \"Cook Together\", \"description\": \"Cover and cook on low heat until the rice is completely cooked.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Fluff the biryani gently and serve hot.\", \"step_number\": 5}]'),(17,2,'Chicken Biryani','chicken-biryani','Aromatic basmati rice cooked with tender chicken and flavorful spices.',25,40,4,'Chicken-Biryani.jpg','https://www.youtube.com/embed/PVO-4Jnjpfk','Marinate the chicken and prepare the rice separately. Cook the chicken with onion and tomato, layer it with rice and cook until the flavors combine.','[{\"title\": \"Marinate Chicken\", \"description\": \"Mix chicken with yogurt and ginger garlic paste.\", \"step_number\": 1}, {\"title\": \"Prepare Rice\", \"description\": \"Cook the basmati rice until partially done.\", \"step_number\": 2}, {\"title\": \"Cook Chicken\", \"description\": \"Cook the marinated chicken with onion and tomato.\", \"step_number\": 3}, {\"title\": \"Layer\", \"description\": \"Layer the rice over the chicken mixture.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Cover and cook until completely done, then serve hot.\", \"step_number\": 5}]'),(18,2,'Tomato Rice','tomato-rice','A simple and tasty rice dish prepared with fresh tomatoes and aromatic ingredients.',10,20,4,'Tomato-Rice.jpg','https://www.youtube.com/embed/njK2iywAJ_k','Cook the tomatoes and onions until soft and flavorful. Add the cooked rice and mix everything together.','[{\"title\": \"Prepare Rice\", \"description\": \"Cook the rice and keep it ready.\", \"step_number\": 1}, {\"title\": \"Cook Tomato\", \"description\": \"Cook chopped tomatoes and onion until soft.\", \"step_number\": 2}, {\"title\": \"Add Ingredients\", \"description\": \"Add green chilli and ginger.\", \"step_number\": 3}, {\"title\": \"Add Rice\", \"description\": \"Add the cooked rice and mix gently.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Garnish with coriander leaves and serve.\", \"step_number\": 5}]'),(19,2,'Lemon Rice','lemon-rice','A refreshing South Indian rice dish with a bright lemon flavor.',10,15,4,'lemon.jpg','https://www.youtube.com/embed/S582ox6c4l4','Prepare the seasoning, add cooked rice and finish with fresh lemon juice.','[{\"title\": \"Cook Rice\", \"description\": \"Prepare the rice and allow it to cool slightly.\", \"step_number\": 1}, {\"title\": \"Prepare Seasoning\", \"description\": \"Cook the peanuts, green chilli and ginger.\", \"step_number\": 2}, {\"title\": \"Add Rice\", \"description\": \"Add the cooked rice and mix gently.\", \"step_number\": 3}, {\"title\": \"Add Lemon\", \"description\": \"Add fresh lemon juice and mix well.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Serve the lemon rice warm or at room temperature.\", \"step_number\": 5}]'),(20,2,'Curd Rice','curd-rice','A creamy and comforting South Indian rice dish made with yogurt.',10,10,4,'curd.jpg','https://www.youtube.com/embed/c6S9skegZ1c','Mash the cooked rice gently and mix with curd and milk. Add the prepared seasoning and serve.','[{\"title\": \"Prepare Rice\", \"description\": \"Mash the cooked rice gently.\", \"step_number\": 1}, {\"title\": \"Add Curd\", \"description\": \"Mix the rice with fresh curd.\", \"step_number\": 2}, {\"title\": \"Add Milk\", \"description\": \"Add a little milk for a creamy texture.\", \"step_number\": 3}, {\"title\": \"Prepare Seasoning\", \"description\": \"Prepare the seasoning with green chilli and ginger.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Mix everything well and serve.\", \"step_number\": 5}]'),(21,2,'Sambar Rice','sambar-rice','A comforting one-pot South Indian meal combining rice, dal and vegetables.',15,30,4,'sambar.jpg','https://www.youtube.com/embed/k-URfLU99RQ','Cook rice, dal and vegetables together with sambar ingredients until soft and well combined.','[{\"title\": \"Cook Dal\", \"description\": \"Cook the toor dal until soft.\", \"step_number\": 1}, {\"title\": \"Cook Vegetables\", \"description\": \"Cook the vegetables with tomato.\", \"step_number\": 2}, {\"title\": \"Prepare Sambar\", \"description\": \"Combine the cooked dal and vegetables.\", \"step_number\": 3}, {\"title\": \"Add Rice\", \"description\": \"Add cooked rice and mix well.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Cook for a few minutes and serve hot.\", \"step_number\": 5}]'),(22,2,'Rajma Rice','rajma-rice','A hearty North Indian meal of kidney bean curry served with steamed rice.',20,35,4,'rajma.jpg','https://www.youtube.com/embed/nnvk38T-iq8','Soak and cook the rajma until soft. Prepare a tomato-onion base and combine it with the cooked beans. Serve with rice.','[{\"title\": \"Soak Rajma\", \"description\": \"Soak rajma in water before cooking.\", \"step_number\": 1}, {\"title\": \"Cook Rajma\", \"description\": \"Cook the rajma until soft.\", \"step_number\": 2}, {\"title\": \"Prepare Gravy\", \"description\": \"Cook onion, tomato and ginger garlic paste.\", \"step_number\": 3}, {\"title\": \"Combine\", \"description\": \"Add the cooked rajma and simmer.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Serve hot with steamed rice.\", \"step_number\": 5}]'),(23,2,'Veg Fried Rice','veg-fried-rice','Flavorful fried rice tossed with colorful vegetables and cooked rice.',15,15,4,'friedrice.jpg','https://www.youtube.com/embed/bXgxzzNm0U8','Stir-fry the vegetables on high heat and toss them with cooked rice until everything is well combined.','[{\"title\": \"Prepare Rice\", \"description\": \"Cook the rice and allow it to cool.\", \"step_number\": 1}, {\"title\": \"Chop Vegetables\", \"description\": \"Chop the vegetables into small pieces.\", \"step_number\": 2}, {\"title\": \"Stir Fry\", \"description\": \"Stir-fry the vegetables on high heat.\", \"step_number\": 3}, {\"title\": \"Add Rice\", \"description\": \"Add the cooked rice and mix well.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Garnish with spring onion and serve.\", \"step_number\": 5}]'),(24,2,'Chicken Fried Rice','chicken-fried-rice','A delicious fried rice prepared with chicken and fresh vegetables.',15,20,4,'chickenrice.jpg','https://www.youtube.com/embed/rcbCY26CLX4','Cook the chicken and vegetables separately, then toss them with cooked rice until well combined.','[{\"title\": \"Cook Chicken\", \"description\": \"Cook the chicken pieces until completely done.\", \"step_number\": 1}, {\"title\": \"Prepare Vegetables\", \"description\": \"Stir-fry the chopped vegetables.\", \"step_number\": 2}, {\"title\": \"Add Chicken\", \"description\": \"Add the cooked chicken to the vegetables.\", \"step_number\": 3}, {\"title\": \"Add Rice\", \"description\": \"Add cooked rice and mix everything well.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Garnish with spring onion and serve hot.\", \"step_number\": 5}]'),(25,2,'Paneer Butter Masala + Roti','paneer-butter-masala-roti','Soft paneer cooked in a rich tomato-based gravy served with warm roti.',15,25,4,'roti.jpg','https://www.youtube.com/embed/532fW5hNi1Y','Prepare a smooth tomato-based gravy, add paneer and butter, and cook until the flavors combine. Serve with roti.','[{\"title\": \"Prepare Gravy\", \"description\": \"Cook onion and tomato and prepare a smooth gravy.\", \"step_number\": 1}, {\"title\": \"Add Paneer\", \"description\": \"Add paneer cubes to the gravy.\", \"step_number\": 2}, {\"title\": \"Add Butter\", \"description\": \"Add butter and cook gently.\", \"step_number\": 3}, {\"title\": \"Prepare Roti\", \"description\": \"Cook fresh rotis on a hot pan.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Serve paneer butter masala with warm roti.\", \"step_number\": 5}]'),(26,2,'Chole + Rice','chole-rice','Spiced chickpea curry served with fluffy steamed rice.',20,30,4,'chole.jpg','https://www.youtube.com/embed/dQKeBJECYoI','Cook the chickpeas until soft and prepare a flavorful onion-tomato gravy. Serve the chole with steamed rice.','[{\"title\": \"Soak Chickpeas\", \"description\": \"Soak chickpeas before cooking.\", \"step_number\": 1}, {\"title\": \"Cook Chickpeas\", \"description\": \"Cook the chickpeas until soft.\", \"step_number\": 2}, {\"title\": \"Prepare Gravy\", \"description\": \"Cook onion, tomato and ginger garlic paste.\", \"step_number\": 3}, {\"title\": \"Combine\", \"description\": \"Add chickpeas to the gravy and simmer.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Serve hot with steamed rice.\", \"step_number\": 5}]'),(27,2,'Vegetable Pulao','vegetable-pulao','Fragrant basmati rice cooked with colorful vegetables for a simple meal.',15,25,4,'pulao.jpg','https://www.youtube.com/embed/8XRpoWliwGM','Cook the vegetables with onion and ginger, add soaked rice and water, then cook until the rice is fluffy.','[{\"title\": \"Wash Rice\", \"description\": \"Wash and soak the basmati rice.\", \"step_number\": 1}, {\"title\": \"Cook Vegetables\", \"description\": \"Cook the vegetables with onion and ginger.\", \"step_number\": 2}, {\"title\": \"Add Rice\", \"description\": \"Add the soaked rice and mix gently.\", \"step_number\": 3}, {\"title\": \"Cook\", \"description\": \"Add water and cook until the rice is fluffy.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Garnish and serve hot.\", \"step_number\": 5}]'),(28,2,'Chicken Curry + Rice','chicken-curry-rice','Tender chicken cooked in a flavorful curry and served with steamed rice.',20,35,4,'curry.jpg','https://www.youtube.com/embed/AoPqKq4Wv_E','Cook the chicken with onion, tomato and aromatic ingredients until tender. Serve the curry with steamed rice.','[{\"title\": \"Prepare Chicken\", \"description\": \"Clean and prepare the chicken pieces.\", \"step_number\": 1}, {\"title\": \"Cook Base\", \"description\": \"Cook onion, tomato and ginger garlic paste.\", \"step_number\": 2}, {\"title\": \"Add Chicken\", \"description\": \"Add chicken and cook with the gravy.\", \"step_number\": 3}, {\"title\": \"Simmer\", \"description\": \"Cover and cook until the chicken becomes tender.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Serve hot with steamed rice.\", \"step_number\": 5}]'),(29,2,'Dal Tadka + Rice','dal-tadka-rice','Comforting yellow dal with a flavorful tadka served alongside steamed rice.',10,25,4,'dal.jpg','https://www.youtube.com/embed/XzKkkMdo7Jk','Cook the dal until soft and prepare a simple tadka. Mix the tadka with dal and serve with rice.','[{\"title\": \"Cook Dal\", \"description\": \"Wash and cook the dal until soft.\", \"step_number\": 1}, {\"title\": \"Prepare Rice\", \"description\": \"Cook the rice separately.\", \"step_number\": 2}, {\"title\": \"Prepare Tadka\", \"description\": \"Prepare the onion and tomato tadka.\", \"step_number\": 3}, {\"title\": \"Mix\", \"description\": \"Add the tadka to the cooked dal.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Serve hot dal with steamed rice.\", \"step_number\": 5}]'),(30,2,'Veg Noodles','veg-noodles','Quick and tasty noodles tossed with colorful vegetables.',10,15,4,'noodle.jpg','https://www.youtube.com/embed/xWZeQBLV6q4','Boil the noodles and stir-fry them with fresh vegetables until everything is well combined.','[{\"title\": \"Boil Noodles\", \"description\": \"Cook the noodles according to the package instructions.\", \"step_number\": 1}, {\"title\": \"Prepare Vegetables\", \"description\": \"Slice the vegetables into thin pieces.\", \"step_number\": 2}, {\"title\": \"Stir Fry\", \"description\": \"Stir-fry the vegetables on high heat.\", \"step_number\": 3}, {\"title\": \"Add Noodles\", \"description\": \"Add the cooked noodles and mix well.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Garnish with spring onion and serve hot.\", \"step_number\": 5}]'),(31,3,'Roti + Dal','roti-dal','A simple and comforting combination of soft roti and nutritious dal.',10,25,4,'rotidal.jpg','https://www.youtube.com/embed/No_5EYvEH-0','Prepare a soft wheat dough for roti and cook the dal with tomato and onion until soft and flavorful.','[{\"title\": \"Prepare Dough\", \"description\": \"Mix wheat flour with water and prepare a soft dough.\", \"step_number\": 1}, {\"title\": \"Prepare Dal\", \"description\": \"Wash and cook the dal until soft.\", \"step_number\": 2}, {\"title\": \"Prepare Gravy\", \"description\": \"Cook onion, tomato and green chilli.\", \"step_number\": 3}, {\"title\": \"Combine\", \"description\": \"Mix the cooked dal with the prepared gravy.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Cook the rotis on a hot pan and serve with dal.\", \"step_number\": 5}]'),(32,3,'Aloo Gobi','aloo-gobi','A flavorful North Indian vegetable dish made with potatoes and cauliflower.',15,25,4,'alogobi.jpg','https://www.youtube.com/embed/YyfkOpgNL_Q','Cook potatoes and cauliflower with onion and tomato until tender and flavorful.','[{\"title\": \"Prepare Vegetables\", \"description\": \"Wash and cut potatoes and cauliflower into pieces.\", \"step_number\": 1}, {\"title\": \"Cook Onion\", \"description\": \"Cook chopped onion until soft.\", \"step_number\": 2}, {\"title\": \"Add Tomato\", \"description\": \"Add chopped tomatoes and green chilli.\", \"step_number\": 3}, {\"title\": \"Add Vegetables\", \"description\": \"Add potatoes and cauliflower and cook until tender.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Garnish with coriander leaves and serve hot.\", \"step_number\": 5}]'),(33,3,'Palak Paneer','palak-paneer','Soft paneer cubes cooked in a smooth and flavorful spinach gravy.',15,25,4,'palak.jpg','https://www.youtube.com/embed/cRsAQeR5dbI','Blanch and blend the spinach into a smooth puree. Cook it with onion and tomato, then add paneer cubes.','[{\"title\": \"Prepare Spinach\", \"description\": \"Wash and blanch the spinach.\", \"step_number\": 1}, {\"title\": \"Make Puree\", \"description\": \"Blend the spinach into a smooth puree.\", \"step_number\": 2}, {\"title\": \"Prepare Gravy\", \"description\": \"Cook onion, tomato and ginger.\", \"step_number\": 3}, {\"title\": \"Add Spinach\", \"description\": \"Add the spinach puree and cook gently.\", \"step_number\": 4}, {\"title\": \"Add Paneer\", \"description\": \"Add paneer cubes and simmer before serving.\", \"step_number\": 5}]'),(34,3,'Vegetable Manchurian','vegetable-manchurian','Crispy vegetable balls cooked in a flavorful Indo-Chinese sauce.',20,25,4,'vegman.jpg','https://www.youtube.com/embed/zSYmtXhs_oA','Prepare vegetable balls, cook them until golden and toss them with a flavorful sauce.','[{\"title\": \"Prepare Vegetables\", \"description\": \"Finely chop the cabbage, carrot and capsicum.\", \"step_number\": 1}, {\"title\": \"Make Balls\", \"description\": \"Mix the vegetables with corn flour and shape into small balls.\", \"step_number\": 2}, {\"title\": \"Cook Balls\", \"description\": \"Cook the vegetable balls until golden.\", \"step_number\": 3}, {\"title\": \"Prepare Sauce\", \"description\": \"Cook the vegetables with soy sauce.\", \"step_number\": 4}, {\"title\": \"Combine\", \"description\": \"Add the vegetable balls to the sauce and serve.\", \"step_number\": 5}]'),(35,3,'Chicken Tikka','chicken-tikka','Tender chicken pieces marinated with yogurt and flavorful ingredients.',30,25,4,'tikka.jpg','https://www.youtube.com/embed/6No7g2GptXY','Marinate chicken pieces with yogurt and other ingredients, then cook until completely done.','[{\"title\": \"Prepare Marinade\", \"description\": \"Mix yogurt, lemon juice and ginger garlic paste.\", \"step_number\": 1}, {\"title\": \"Marinate Chicken\", \"description\": \"Coat the chicken pieces with the marinade.\", \"step_number\": 2}, {\"title\": \"Add Vegetables\", \"description\": \"Prepare onion and capsicum pieces.\", \"step_number\": 3}, {\"title\": \"Cook\", \"description\": \"Cook the marinated chicken and vegetables until completely done.\", \"step_number\": 4}, {\"title\": \"Serve\", \"description\": \"Serve 